{"title": "[Tropobeat] CCI ops: data health", "type": "vega", "aggs": [], "params": {"spec": "{
 "$schema": "https://vega.github.io/schema/vega/v5.json",
 "autosize": {
  "type": "fit",
  "contains": "padding"
 },
 "padding": {
  "left": 20,
  "right": 20,
  "top": 18,
  "bottom": 12
 },
 "background": "#0F1F2C",
 "config": {
  "view": {
   "stroke": null
  },
  "legend": {
   "labelColor": "#8DA2B2",
   "labelFont": "ui-monospace,Menlo,Consolas,monospace",
   "labelFontSize": 11.5,
   "symbolType": "square",
   "symbolSize": 100,
   "symbolStrokeWidth": 0,
   "columnPadding": 14,
   "layout": {
    "top": {
     "anchor": "end"
    }
   }
  },
  "text": {
   "font": "\"Inter\",\"Segoe UI\",system-ui,sans-serif",
   "fill": "#E4EDF3"
  }
 },
 "title": {
  "text": "Data health",
  "subtitle": "LAST 48 H · AGES FROM NOW",
  "anchor": "start",
  "frame": "group",
  "offset": 12,
  "color": "#E4EDF3",
  "font": "\"Barlow Condensed\",\"Roboto Condensed\",\"Arial Narrow\",sans-serif",
  "fontSize": 22,
  "fontWeight": 600,
  "subtitleColor": "#8DA2B2",
  "subtitleFont": "ui-monospace,Menlo,Consolas,monospace",
  "subtitleFontSize": 11,
  "subtitlePadding": 4
 },
 "signals": [
  {
   "name": "rowh",
   "value": 52
  }
 ],
 "data": [
  {
   "name": "healthRaw",
   "url": {
    "index": "tropobeat-*",
    "body": {
     "size": 0,
     "aggs": {
      "sweep": {
       "filter": {
        "term": {
         "tropobeat.correlation_trace.category": "sweep"
        }
       },
       "aggs": {
        "top": {
         "top_hits": {
          "size": 1,
          "sort": [
           {
            "@timestamp": "desc"
           }
          ],
          "_source": false,
          "fields": [
           "@timestamp",
           "tropobeat.correlation_trace.sweep.instances",
           "tropobeat.correlation_trace.sweep.pairs",
           "tropobeat.correlation_trace.sweep.not_clear"
          ]
         }
        }
       }
      },
      "poll": {
       "filter": {
        "term": {
         "metricset.name": "weather"
        }
       },
       "aggs": {
        "t": {
         "terms": {
          "field": "@timestamp",
          "size": 1,
          "order": {
           "_key": "desc"
          }
         },
         "aggs": {
          "paths": {
           "cardinality": {
            "field": "tropobeat.path_ids"
           }
          },
          "lrfs": {
           "cardinality": {
            "field": "tropobeat.lrf_codes"
           }
          },
          "nodata": {
           "filter": {
            "bool": {
             "must_not": {
              "exists": {
               "field": "tropobeat.ducting_state"
              }
             }
            }
           },
           "aggs": {
            "p": {
             "cardinality": {
              "field": "tropobeat.path_ids"
             }
            }
           }
          }
         }
        }
       }
      },
      "base": {
       "filter": {
        "term": {
         "metricset.name": "baseline"
        }
       },
       "aggs": {
        "r": {
         "terms": {
          "field": "tropobeat.baseline.run_id",
          "size": 1,
          "order": {
           "_key": "desc"
          }
         },
         "aggs": {
          "last": {
           "max": {
            "field": "@timestamp"
           }
          },
          "ok": {
           "filter": {
            "term": {
             "tropobeat.baseline.status": "ok"
            }
           }
          }
         }
        }
       }
      },
      "disc": {
       "filter": {
        "term": {
         "metricset.name": "cochannel"
        }
       },
       "aggs": {
        "r": {
         "terms": {
          "field": "tropobeat.discovery_run_id",
          "size": 1,
          "order": {
           "_key": "desc"
          }
         },
         "aggs": {
          "last": {
           "max": {
            "field": "@timestamp"
           }
          },
          "paths": {
           "cardinality": {
            "field": "tropobeat.path_ids"
           }
          },
          "lrfs": {
           "cardinality": {
            "field": "tropobeat.lrf_codes"
           }
          }
         }
        }
       }
      }
     },
     "query": {
      "bool": {
       "must": [
        "%dashboard_context-must_clause%",
        {
         "range": {
          "@timestamp": {
           "gte": "now-48h"
          }
         }
        }
       ],
       "must_not": [
        "%dashboard_context-must_not_clause%"
       ],
       "filter": [
        "%dashboard_context-filter_clause%"
       ]
      }
     }
    }
   }
  },
  {
   "name": "h0",
   "source": "healthRaw",
   "transform": [
    {
     "type": "formula",
     "as": "i",
     "expr": "0"
    },
    {
     "type": "formula",
     "as": "name",
     "expr": "'Correlation sweeps'"
    },
    {
     "type": "formula",
     "as": "note",
     "expr": "(datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null) ? (datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['tropobeat.correlation_trace.sweep.instances'][0] + ' inputs, ' + (datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['tropobeat.correlation_trace.sweep.pairs'][0] + ' pairs, ' + (datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['tropobeat.correlation_trace.sweep.not_clear'][0] + ' not clear' : 'No sweep records: is the correlator on?'"
    },
    {
     "type": "formula",
     "as": "value",
     "expr": "((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null) ? toDate((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['@timestamp'][0]) : null) == null ? 'none in 48 h' : (now() - ((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null) ? toDate((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['@timestamp'][0]) : null)) < 90000 ? round((now() - ((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null) ? toDate((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['@timestamp'][0]) : null)) / 1000) + ' s ago' : (now() - ((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null) ? toDate((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['@timestamp'][0]) : null)) < 5400000 ? round((now() - ((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null) ? toDate((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['@timestamp'][0]) : null)) / 60000) + ' min ago' : round((now() - ((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null) ? toDate((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['@timestamp'][0]) : null)) / 3600000) + ' h ago'"
    },
    {
     "type": "formula",
     "as": "status",
     "expr": "!(datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null) ? 'bad' : now() - toDate((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['@timestamp'][0]) < 180000 ? 'ok' : now() - toDate((datum.aggregations.sweep.top.hits.hits[0] ? datum.aggregations.sweep.top.hits.hits[0].fields : null)['@timestamp'][0]) < 900000 ? 'warn' : 'bad'"
    }
   ]
  },
  {
   "name": "h1",
   "source": "healthRaw",
   "transform": [
    {
     "type": "formula",
     "as": "i",
     "expr": "1"
    },
    {
     "type": "formula",
     "as": "name",
     "expr": "'Weather poll'"
    },
    {
     "type": "formula",
     "as": "note",
     "expr": "datum.aggregations.poll.t.buckets[0] ? format(datum.aggregations.poll.t.buckets[0].paths.value, ',') + ' paths at ' + datum.aggregations.poll.t.buckets[0].lrfs.value + ' LRFs' : 'No weather events'"
    },
    {
     "type": "formula",
     "as": "value",
     "expr": "(datum.aggregations.poll.t.buckets[0] ? datum.aggregations.poll.t.buckets[0].key : null) == null ? 'none in 48 h' : (now() - (datum.aggregations.poll.t.buckets[0] ? datum.aggregations.poll.t.buckets[0].key : null)) < 90000 ? round((now() - (datum.aggregations.poll.t.buckets[0] ? datum.aggregations.poll.t.buckets[0].key : null)) / 1000) + ' s ago' : (now() - (datum.aggregations.poll.t.buckets[0] ? datum.aggregations.poll.t.buckets[0].key : null)) < 5400000 ? round((now() - (datum.aggregations.poll.t.buckets[0] ? datum.aggregations.poll.t.buckets[0].key : null)) / 60000) + ' min ago' : round((now() - (datum.aggregations.poll.t.buckets[0] ? datum.aggregations.poll.t.buckets[0].key : null)) / 3600000) + ' h ago'"
    },
    {
     "type": "formula",
     "as": "status",
     "expr": "datum.aggregations.poll.t.buckets[0] && now() - datum.aggregations.poll.t.buckets[0].key < 4500000 ? 'ok' : 'bad'"
    }
   ]
  },
  {
   "name": "h2",
   "source": "healthRaw",
   "transform": [
    {
     "type": "formula",
     "as": "i",
     "expr": "2"
    },
    {
     "type": "formula",
     "as": "name",
     "expr": "'Baselines'"
    },
    {
     "type": "formula",
     "as": "note",
     "expr": "datum.aggregations.base.r.buckets[0] ? 'Run ' + timeFormat(datum.aggregations.base.r.buckets[0].last.value, '%d %b %H:%M') + ' · ' + format(datum.aggregations.base.r.buckets[0].doc_count, ',') + ' inputs' : 'No baseline run'"
    },
    {
     "type": "formula",
     "as": "value",
     "expr": "datum.aggregations.base.r.buckets[0] ? format(datum.aggregations.base.r.buckets[0].ok.doc_count, ',') + ' ok' : 'none in 48 h'"
    },
    {
     "type": "formula",
     "as": "status",
     "expr": "datum.aggregations.base.r.buckets[0] && datum.aggregations.base.r.buckets[0].ok.doc_count > 0 && now() - datum.aggregations.base.r.buckets[0].last.value < 93600000 ? 'ok' : 'warn'"
    }
   ]
  },
  {
   "name": "h3",
   "source": "healthRaw",
   "transform": [
    {
     "type": "formula",
     "as": "i",
     "expr": "3"
    },
    {
     "type": "formula",
     "as": "name",
     "expr": "'Co-channel discovery'"
    },
    {
     "type": "formula",
     "as": "note",
     "expr": "datum.aggregations.disc.r.buckets[0] ? 'Run ' + timeFormat(datum.aggregations.disc.r.buckets[0].last.value, '%d %b %H:%M') + ' · ' + datum.aggregations.disc.r.buckets[0].lrfs.value + ' LRFs' : 'No discovery run'"
    },
    {
     "type": "formula",
     "as": "value",
     "expr": "datum.aggregations.disc.r.buckets[0] ? format(datum.aggregations.disc.r.buckets[0].paths.value, ',') + ' paths' : 'none in 48 h'"
    },
    {
     "type": "formula",
     "as": "status",
     "expr": "datum.aggregations.disc.r.buckets[0] && now() - datum.aggregations.disc.r.buckets[0].last.value < 93600000 ? 'ok' : 'warn'"
    }
   ]
  },
  {
   "name": "h4",
   "source": "healthRaw",
   "transform": [
    {
     "type": "formula",
     "as": "i",
     "expr": "4"
    },
    {
     "type": "formula",
     "as": "name",
     "expr": "'Paths without weather'"
    },
    {
     "type": "formula",
     "as": "note",
     "expr": "'Latest poll · they count as ducting unknown'"
    },
    {
     "type": "formula",
     "as": "value",
     "expr": "datum.aggregations.poll.t.buckets[0] ? format(datum.aggregations.poll.t.buckets[0].nodata.p.value, ',') : '–'"
    },
    {
     "type": "formula",
     "as": "status",
     "expr": "datum.aggregations.poll.t.buckets[0] && datum.aggregations.poll.t.buckets[0].nodata.p.value == 0 ? 'ok' : 'warn'"
    }
   ]
  },
  {
   "name": "health",
   "source": [
    "h0",
    "h1",
    "h2",
    "h3",
    "h4"
   ],
   "transform": [
    {
     "type": "formula",
     "as": "y",
     "expr": "datum.i * rowh"
    }
   ]
  }
 ],
 "scales": [
  {
   "name": "status",
   "type": "ordinal",
   "domain": [
    "ok",
    "warn",
    "bad"
   ],
   "range": [
    "#6BD48A",
    "#E0A458",
    "#FF6B5E"
   ]
  }
 ],
 "marks": [
  {
   "type": "symbol",
   "from": {
    "data": "health"
   },
   "encode": {
    "update": {
     "x": {
      "value": 5
     },
     "y": {
      "signal": "datum.y + rowh / 2 - 2"
     },
     "shape": {
      "value": "circle"
     },
     "size": {
      "value": 100
     },
     "fill": {
      "scale": "status",
      "field": "status"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "health"
   },
   "encode": {
    "update": {
     "x": {
      "value": 22
     },
     "y": {
      "signal": "datum.y + 20"
     },
     "text": {
      "field": "name"
     },
     "fontSize": {
      "value": 14
     },
     "fill": {
      "value": "#E4EDF3"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "health"
   },
   "encode": {
    "update": {
     "x": {
      "value": 22
     },
     "y": {
      "signal": "datum.y + 38"
     },
     "text": {
      "field": "note"
     },
     "limit": {
      "signal": "width - 115"
     },
     "fontSize": {
      "value": 12.5
     },
     "fill": {
      "value": "#8DA2B2"
     }
    }
   }
  },
  {
   "type": "text",
   "from": {
    "data": "health"
   },
   "encode": {
    "update": {
     "x": {
      "signal": "width"
     },
     "y": {
      "signal": "datum.y + rowh / 2 - 2"
     },
     "align": {
      "value": "right"
     },
     "baseline": {
      "value": "middle"
     },
     "text": {
      "field": "value"
     },
     "font": {
      "value": "ui-monospace,Menlo,Consolas,monospace"
     },
     "fontSize": {
      "value": 13
     },
     "fill": {
      "signal": "datum.status == 'ok' ? '#C3D1DB' : scale('status', datum.status)"
     }
    }
   }
  },
  {
   "type": "rule",
   "from": {
    "data": "health"
   },
   "encode": {
    "update": {
     "x": {
      "value": 0
     },
     "x2": {
      "signal": "width"
     },
     "y": {
      "signal": "datum.y + rowh - 4.5"
     },
     "stroke": {
      "value": "#1B3042"
     }
    }
   }
  }
 ]
}"}}
